corrected_code:
const loadArticle = async (req, res, next) => {
  res.locals.article = await Article.findByPk(req.params.articleId);
  if (!res.locals.article) return res.status(404).send('Article not found');
  next();
};

const requireEditor = (req, res, next) => {
  if (req.user.role !== 'editor') return res.status(403).send('Forbidden: must have editor role');
  if (res.locals.article.publicationId !== req.user.publicationId) {
    return res.status(403).send('Forbidden: editor not assigned to this publication');
  }
  next();
};

app.put('/api/cms/articles/:articleId', authJwt, loadArticle, requireEditor, async (req, res) => {
  await res.locals.article.update(req.body);
  res.json(res.locals.article);
});
